Chào bạn, dưới đây là một component React hoàn chỉnh sử dụng **Functional Component** và **Hooks** (`useState`) để thực hiện đầy đủ các yêu cầu của bạn.

Tôi sẽ viết code bao gồm cả phần logic và CSS inline (viết trực tiếp trong JS) để bạn có thể copy và chạy ngay lập tức mà không cần tạo thêm file CSS.

```jsx
import React, { useState } from 'react';

const TodoApp = () => {
  // State quản lý danh sách todo
  const [todos, setTodos] = useState([]);
  // State quản lý nội dung đang nhập ở ô input
  const [inputValue, setInputValue] = useState('');

  // Hàm thêm công việc mới
  const addTodo = (e) => {
    e.preventDefault(); // Ngăn trang web load lại khi nhấn Enter hoặc bấm nút submit
    if (inputValue.trim() === '') return; // Không cho phép thêm nếu chuỗi rỗng

    const newTodo = {
      id: Date.now(), // Dùng timestamp làm ID duy nhất
      text: inputValue,
      isCompleted: false,
    };

    setTodos([...todos, newTodo]);
    setInputValue(''); // Xóa trắng ô input sau khi thêm
  };

  // Hàm đánh dấu hoàn thành/chưa hoàn thành (toggle)
  const toggleTodo = (id) => {
    const updatedTodos = todos.map((todo) => {
      if (todo.id === id) {
        return { ...todo, isCompleted: !todo.isCompleted };
      }
      return todo;
    });
    setTodos(updatedTodos);
  };

  // Hàm xóa một công việc
  const deleteTodo = (id) => {
    const filteredTodos = todos.filter((todo) => todo.id !== id);
    setTodos(filteredTodos);
  };

  // Tính số lượng việc chưa xong
  const remainingTasks = todos.filter((todo) => !todo.isCompleted).length;

  // --- CSS Inline Styles ---
  const styles = {
    container: { fontFamily: 'Arial, sans-serif', maxWidth: '400px', margin: '50px auto', padding: '20px', boxShadow: '0 0 10px rgba(0,0,0,0.1)', borderRadius: '8px' },
    header: { textAlign: 'center', color: '#333' },
    inputGroup: { display: 'flex', marginBottom: '20px' },
    input: { flex: 1, padding: '10px', border: '1px solid #ccc', borderRadius: '4px 0 0 4px', outline: 'none' },
    addButton: { padding: '10px 15px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '0 4px 4px 0', cursor: 'pointer' },
    todoList: { listStyle: 'none', padding: 0 },
    todoItem: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px', borderBottom: '1px solid #eee' },
    todoText: (isCompleted) => ({
      flex: 1,
      cursor: 'pointer',
      textDecoration: isCompleted ? 'line-through' : 'none',
      color: isCompleted ? '#888' : '#000',
    }),
    deleteButton: { backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' },
    counter: { marginTop: '20px', fontSize: '0.9rem', color: '#666', fontStyle: 'italic' }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>My Todo List</h2>

      {/* Form nhập liệu */}
      <form onSubmit={addTodo} style={styles.inputGroup}>
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          placeholder="Nhập việc cần làm..."
          style={styles.input}
        />
        <button type="submit" style={styles.addButton}>Thêm</button>
      </form>

      {/* Danh sách Todo */}
      <ul style={styles.todoList}>
        {todos.map((todo) => (
          <li key={todo.id} style={styles.todoItem}>
            <span
              onClick={() => toggleTodo(todo.id)}
              style={styles.todoText(todo.isCompleted)}
            >
              {todo.text}
            </span>
            <button 
              onClick={() => deleteTodo(todo.id)} 
              style={styles.deleteButton}
            >
              Xóa
            </button>
          </li>
        ))}
      </ul>

      {/* Hiển thị số việc chưa xong */}
      <div style={styles.counter}>
        Số việc chưa xong: {remainingTasks}
      </div>
    </div>
  );
};

export default TodoApp;
```

### Giải thích các điểm chính trong code:

1.  **State Management (`useState`)**:
    *   `todos`: Một mảng chứa các object `{ id, text, isCompleted }`. Đây là "nguồn sự thật" duy nhất của ứng dụng.
    *   `inputValue`: Lưu trữ chuỗi ký tự người dùng đang gõ vào ô input để kiểm soát component (Controlled Component).

2.  **Logic xử lý**:
    *   **Thêm (`addTodo`)**: Sử dụng toán tử spread `[...todos, newTodo]` để tạo một mảng mới thay vì dùng `.push()` (vì trong React không được phép mutate state trực tiếp).
    *   **Đánh dấu hoàn thành (`toggleTodo`)**: Dùng hàm `.map()` để duyệt qua danh sách. Nếu tìm thấy ID trùng khớp, ta trả về một object mới đã đảo ngược giá trị `isCompleted`.
    *   **Xóa (`deleteTodo`)**: Dùng hàm `.filter()` để tạo ra một mảng mới loại bỏ phần tử có ID được chọn.
    *   **Tính toán số việc chưa xong**: Sử dụng `.filter().length` ngay trong quá trình render để luôn hiển thị con số chính xác nhất theo trạng thái hiện tại của `todos`.

3.  **Giao diện (UI)**:
    *   Sử dụng **Conditional Styling**: Đoạn `textDecoration: isCompleted ? 'line-through' : 'none'` giúp thay đổi kiểu chữ ngay lập tức khi người dùng click vào dòng chữ.
    *   `e.preventDefault()` trong hàm submit cực kỳ quan trọng để ngăn trình duyệt load lại trang (hành vi mặc định của thẻ `<form>`).

